//! Python stub generation.

use crate::plugin::{snake_case, upper_camel, MethodKind, ProtoFile, Service};

pub fn generate(file: &ProtoFile) -> String {
    let mut out = String::new();
    out.push_str("# @generated by protoc-gen-qrpc. Do not edit.\n");
    out.push_str(
        "# Messages are generated by the native protobuf plugin; qRPC stubs move bytes.\n\n",
    );
    for service in &file.services {
        write_service(&mut out, service);
    }
    out
}

fn write_service(out: &mut String, service: &Service) {
    let client_name = format!("{}Client", upper_camel(&service.name));
    let base_name = format!("{}Service", upper_camel(&service.name));
    let register_name = format!("register_{}_service", snake_case(&service.name));

    out.push_str(&format!("class {client_name}:\n"));
    out.push_str("    def __init__(self, channel):\n");
    out.push_str("        self._channel = channel\n\n");
    for method in &service.methods {
        match method.kind {
            MethodKind::Unary => {
                out.push_str(&format!(
                    "    async def {}(self, request: bytes) -> bytes:\n",
                    method.rust_name
                ));
                out.push_str(&format!(
                    "        return await self._channel.unary(\"{}\", request)\n\n",
                    method.route
                ));
            }
            _ => {
                out.push_str(&format!(
                    "    async def {}(self, *args):\n",
                    method.rust_name
                ));
                out.push_str(&format!(
                    "        return await self._channel.stream(\"{}\", *args)\n\n",
                    method.route
                ));
            }
        }
    }

    out.push_str(&format!("class {base_name}:\n"));
    for method in &service.methods {
        out.push_str(&format!(
            "    async def {}(self, *args):\n",
            method.rust_name
        ));
        out.push_str("        raise NotImplementedError\n\n");
    }

    out.push_str(&format!(
        "def {register_name}(server, service: {base_name}):\n"
    ));
    out.push_str(&format!(
        "    server.register_service(\"{}\", service)\n\n",
        service.full_name
    ));
}
